struct ArabicForm { uint32_t cp, iso, fin, ini, med; bool joinNext, joinPrev; };
static const ArabicForm A[] = {
 {0x0621,0xFE80,0,0,0,0,0},{0x0622,0xFE81,0xFE82,0,0,0,1},{0x0623,0xFE83,0xFE84,0,0,0,1},{0x0625,0xFE87,0xFE88,0,0,0,1},{0x0627,0xFE8D,0xFE8E,0,0,0,1},{0x0628,0xFE8F,0xFE90,0xFE91,0xFE92,1,1},{0x0629,0xFE93,0xFE94,0,0,0,1},{0x062A,0xFE95,0xFE96,0xFE97,0xFE98,1,1},{0x062B,0xFE99,0xFE9A,0xFE9B,0xFE9C,1,1},{0x062C,0xFE9D,0xFE9E,0xFE9F,0xFEA0,1,1},{0x062D,0xFEA1,0xFEA2,0xFEA3,0xFEA4,1,1},{0x062E,0xFEA5,0xFEA6,0xFEA7,0xFEA8,1,1},{0x062F,0xFEA9,0xFEAA,0,0,0,1},{0x0630,0xFEAB,0xFEAC,0,0,0,1},{0x0631,0xFEAD,0xFEAE,0,0,0,1},{0x0632,0xFEAF,0xFEB0,0,0,0,1},{0x0633,0xFEB1,0xFEB2,0xFEB3,0xFEB4,1,1},{0x0634,0xFEB5,0xFEB6,0xFEB7,0xFEB8,1,1},{0x0635,0xFEB9,0xFEBA,0xFEBB,0xFEBC,1,1},{0x0636,0xFEBD,0xFEBE,0xFEBF,0xFEC0,1,1},{0x0637,0xFEC1,0xFEC2,0xFEC3,0xFEC4,1,1},{0x0638,0xFEC5,0xFEC6,0xFEC7,0xFEC8,1,1},{0x0639,0xFEC9,0xFECA,0xFECB,0xFECC,1,1},{0x063A,0xFECD,0xFECE,0xFECF,0xFED0,1,1},{0x0641,0xFED1,0xFED2,0xFED3,0xFED4,1,1},{0x0642,0xFED5,0xFED6,0xFED7,0xFED8,1,1},{0x0643,0xFED9,0xFEDA,0xFEDB,0xFEDC,1,1},{0x0644,0xFEDD,0xFEDE,0xFEDF,0xFEE0,1,1},{0x0645,0xFEE1,0xFEE2,0xFEE3,0xFEE4,1,1},{0x0646,0xFEE5,0xFEE6,0xFEE7,0xFEE8,1,1},{0x0647,0xFEE9,0xFEEA,0xFEEB,0xFEEC,1,1},{0x0648,0xFEED,0xFEEE,0,0,0,1},{0x0649,0xFEEF,0xFEF0,0,0,0,1},{0x064A,0xFEF1,0xFEF2,0xFEF3,0xFEF4,1,1}
};
static const ArabicForm *form(uint32_t cp){ for(size_t i=0;i<sizeof(A)/sizeof(A[0]);++i) if(A[i].cp==cp) return &A[i]; return 0; }
static std::vector<uint32_t> utf8(const char *s){ std::vector<uint32_t> v; const unsigned char *p=(const unsigned char*)s; while(*p){ uint32_t c; int n; if(*p<128){c=*p;n=1;} else if((*p&224)==192){c=*p&31;n=2;} else if((*p&240)==224){c=*p&15;n=3;} else {c=*p&7;n=4;} for(int i=1;i<n;++i)c=(c<<6)|(p[i]&63); v.push_back(c); p+=n;} return v; }
static uint32_t shaped(const std::vector<uint32_t>& v,size_t i){ const ArabicForm *c=form(v[i]); if(!c)return v[i]; const ArabicForm *p=i?form(v[i-1]):0,*n=i+1<v.size()?form(v[i+1]):0; bool jp=p&&p->joinNext&&c->joinPrev, jn=n&&c->joinNext&&n->joinPrev; if(jp&&jn&&c->med)return c->med; if(jp&&c->fin)return c->fin; if(jn&&c->ini)return c->ini; return c->iso; }
// Input is logical Arabic order. The first character belongs on the right,
// so glyphs are drawn from index 0 toward the left.
static void arabic(Scene2D *s,FT_Face face,const char *str,int right,int base,Color fg){ std::vector<uint32_t> v=utf8(str); int pen=right; for(size_t i=0;i<v.size();++i){ uint32_t cp=shaped(v,i); FT_UInt gi=FT_Get_Char_Index(face,cp); if(FT_Load_Glyph(face,gi,FT_LOAD_DEFAULT)||FT_Render_Glyph(face->glyph,ft_render_mode_normal))continue; FT_GlyphSlot g=face->glyph; pen-=g->advance.x>>6; for(int y=0;y<g->bitmap.rows;++y)for(int x=0;x<g->bitmap.width;++x){ int dx=pen+x+g->bitmap_left,dy=base+y-g->bitmap_top; if(dx<0||dy<0||dx>=W||dy>=H)continue; uint8_t a=g->bitmap.buffer[y*g->bitmap.pitch+x]; Color c={(uint8_t)(fg.r*a/255),(uint8_t)(fg.g*a/255),(uint8_t)(fg.b*a/255)}; if(a)s->DrawPixel(dx,dy,c); } } }
static void text(Scene2D*s,FT_Face f,const char*t,int x,int y,Color c){s->DrawText((char*)t,f,x,y,BG,c);}
static void base(Scene2D*s,PNG*l,PNG*r,FT_Face en,FT_Face ar){s->FrameBufferFill(BG);s->DrawRectangle(0,0,W,5,RED);s->DrawRectangle(0,H-6,W,3,{70,18,24});l->Draw(s,48,300);r->Draw(s,1488,300);s->DrawRectangle(504,210,912,682,PANEL);s->DrawRectangle(504,210,912,4,RED);s->DrawRectangle(504,210,4,682,{78,22,28});s->DrawRectangle(1412,210,4,682,{78,22,28});text(s,en,"GTXMOD MENU",730,135,WHITE);text(s,en,"PS4 FILE INSTALLER",790,185,MUTED);arabic(s,ar,"اختر إصدارك",1355,300,WHITE);}
static void menu(Scene2D*s,PNG*l,PNG*r,FT_Face en,FT_Face ar,int sel){base(s,l,r,en,ar);const char*v[] = {"1.53","1.56","1.57"};for(int i=0;i<3;++i){int y=350+i*158;s->DrawRectangle(570,y,780,126,i==sel?ROW_SELECTED:ROW);s->DrawRectangle(570,y,7,126,i==sel?RED:Color{63,69,78});if(i==sel)s->DrawRectangle(570,y+122,780,4,RED);text(s,en,v[i],625,y+85,i==sel?WHITE:MUTED);if(i==0)text(s,en,"FILES READY",925,y+77,GREEN);}text(s,en,"UP / DOWN  MOVE       X  SELECT       O  BACK",630,940,WHITE);}
static void sub(Scene2D*s,PNG*l,PNG*r,FT_Face en,FT_Face ar,int screen,const int res[3]){base(s,l,r,en,ar);if(screen==1){arabic(s,ar,"الملفات جاهزة",1350,350,WHITE);text(s,en,"VERSION 1.53",720,430,WHITE);text(s,en,"GTXMOD153.PRX  +  PLUGINS.INI  +  GTX",620,510,MUTED);s->DrawRectangle(680,590,560,112,ROW_SELECTED);s->DrawRectangle(680,590,6,112,RED);text(s,en,"X  INSTALL",835,663,WHITE);text(s,en,"O  BACK",895,785,MUTED);}else if(screen==2){text(s,en,"X / O  BACK",845,680,WHITE);}else if(screen==3){arabic(s,ar,"جاري التثبيت",1350,410,WHITE);text(s,en,"PLEASE WAIT WHILE FILES ARE COPIED",630,520,MUTED);s->DrawRectangle(680,620,560,20,ROW);s->DrawRectangle(680,620,390,20,RED);}else{arabic(s,ar,"نتيجة التثبيت",1350,340,WHITE);const char*n[]={"STEP 1  GTXMOD153.PRX","STEP 2  PLUGINS.INI","STEP 3  GTX FOLDER"};for(int i=0;i<3;++i){int y=420+i*100;s->DrawRectangle(620,y,680,72,ROW);text(s,en,n[i],650,y+49,WHITE);text(s,en,res[i]==0?"OK":"FAILED",1110,y+49,res[i]==0?GREEN:BAD);}text(s,en,"O  BACK TO VERSIONS",785,810,WHITE);}}
int main(void){setvbuf(stdout,0,_IONBF,0);Scene2D scene(W,H,4);if(!scene.Init(0xC000000,2))return 1;scene.SetActiveFrameBuffer(0);FT_Face en=0,ar=0;if(!scene.InitFont(&en,"/app0/assets/fonts/Gontserrat-Regular.ttf",58))return 2;if(!scene.InitFont(&ar,"/app0/assets/fonts/NotoSansArabic-Regular.ttf",58))return 3;PNG left("/app0/assets/images/GTX-side.png"),right("/app0/assets/images/GTX-side.png");if(scePadInit()<0)return 4;OrbisUserServiceInitializeParams up;memset(&up,0,sizeof(up));up.priority=ORBIS_KERNEL_PRIO_FIFO_LOWEST;if(sceUserServiceInitialize(&up)<0)return 5;int uid=-1;if(sceUserServiceGetInitialUser(&uid)<0)return 6;int pad=scePadOpen(uid,ORBIS_PAD_PORT_TYPE_STANDARD,0,0);if(pad<0)return 7;int sel=0,screen=0,res[3]={-1,-1,-1},frame=0;uint32_t prev=0;bool run=true,redraw=true;while(run){OrbisPadData d;memset(&d,0,sizeof(d));if(scePadReadState(pad,&d)>=0){uint32_t cur=d.buttons,pressed=cur&~prev;prev=cur;if(screen==0){if(pressed&ORBIS_PAD_BUTTON_UP){sel=(sel+2)%3;redraw=true;}if(pressed&ORBIS_PAD_BUTTON_DOWN){sel=(sel+1)%3;redraw=true;}if(pressed&ORBIS_PAD_BUTTON_CIRCLE)run=false;if(pressed&ORBIS_PAD_BUTTON_CROSS){screen=(sel==0&&installer_153_ready())?1:2;redraw=true;}}else if(screen==1){if(pressed&ORBIS_PAD_BUTTON_CIRCLE){screen=0;redraw=true;}else if(pressed&ORBIS_PAD_BUTTON_CROSS){screen=3;redraw=true;}}else if(screen==2||screen==4){if(pressed&(ORBIS_PAD_BUTTON_CROSS|ORBIS_PAD_BUTTON_CIRCLE)){screen=0;redraw=true;}}}if(!run)break;if(redraw){if(screen==0)menu(&scene,&left,&right,en,ar,sel);else sub(&scene,&left,&right,en,ar,screen,res);scene.SubmitFlip(frame);scene.FrameWait(frame);scene.FrameBufferSwap();++frame;redraw=false;if(screen==3){installer_run_153(res);screen=4;redraw=true;}}usleep(16000);}scePadClose(pad);return 0;}
